document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("rectangle-form"),t=document.getElementById("rectangle-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("rect-a").value),o=parseFloat(document.getElementById("rect-b").value);if(n<=0||o<=0)return t.textContent="Please enter positive values for sides.",void 0;const r=n*o,d=2*(n+o);t.innerHTML=`<b>Area:</b> ${r.toFixed(4)}<br><b>Perimeter:</b> ${d.toFixed(4)}`})});